Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">Press ▶ Animate to watch electrolysis: O²⁻ oxidizes at the anodes (gas bubbles) and Al³⁺ is reduced at the cathode, thickening the molten aluminum pool.</p>
<button id="animBtn" onclick="toggle_anim()">▶ Animate electrolysis</button>
<label>Applied current: <output id="currentVal">50</output> kA<input id="currentInput" type="range" min="10" max="100" step="5" value="50" oninput="document.getElementById('currentVal').value=this.value;update_current(+this.value)"></label>
<button onclick="trigger_reset()">↺ Reset cell</button>
<span style="font-size:10px">Al produced: <b id="alScore">0</b> mol (scaled)</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Library: svgjs
var W = 640, H = 480;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var running = false, current = 50, alAmount = 0;
var BATH_Y = 218;      // top of electrolyte (under crust)
var AL_BASE_Y = 402;   // cathode floor top where Al sits
var alTopY = 352;      // molten aluminum top surface

/* ---------- static structure (matches source image) ---------- */
// steel shell (dark gray outer box)
draw.rect(560, 300).move(40, 205).fill('#5a5a5a');
// ceramic lining (salmon)
draw.rect(520, 265).move(60, 205).fill('#e8a583');
// electrolyte bath (green)
var bath = draw.rect(472, 190).move(84, BATH_Y).fill('#a8c256');
// molten aluminum layer (light gray, grows upward from floor)
var alLayer = draw.rect(472, AL_BASE_Y - alTopY).move(84, alTopY).fill('#c9c9c9');
// crust strip on top of bath
draw.rect(472, 8).move(84, BATH_Y - 8).fill('#cfdc96').stroke({ color: '#8a9440', width: 1 });

// carbon cathode floor (black slab)
draw.rect(320, 22).move(120, 402).fill('#111');
draw.text('Carbon cathode (−)').move(215, 405).font({ size: 13, fill: '#fff', weight: 'bold' });

// two carbon anodes
function makeAnode(cx) {
  var g = draw.group();
  g.rect(100, 122).move(cx - 50, 190).fill('#111');
  // anode rod + clamp
  g.rect(16, 70).move(cx - 8, 118).fill('#3a3a3a');
  g.rect(56, 16).move(cx - 28, 160).fill('#3a3a3a');
  g.rect(10, 34).move(cx - 22, 176).fill('#3a3a3a');
  g.rect(10, 34).move(cx + 12, 176).fill('#3a3a3a');
  g.text('Carbon\nanode (+)').move(cx - 38, 262).font({ size: 13, fill: '#fff', weight: 'bold' });
  return g;
}
makeAnode(200); makeAnode(360);

// bus bar and +/- terminals
draw.line(192, 120, 530, 120).stroke({ color: '#111', width: 5 });
draw.line(352, 120, 530, 120).stroke({ color: '#111', width: 5 });
draw.text('+').move(532, 104).font({ size: 22, weight: 'bold' });
draw.line(60, 418, 30, 418).stroke({ color: '#111', width: 5 });
draw.text('−').move(16, 404).font({ size: 22, weight: 'bold' });

// exhaust hood outline + arrow + label
draw.path('M 110 205 L 110 52 L 130 52 L 130 26 M 176 26 L 176 52 L 500 52 L 500 205')
  .fill('none').stroke({ color: '#111', width: 2 });
draw.path('M 153 44 L 153 12 M 146 22 L 153 8 L 160 22').fill('none').stroke({ color: '#111', width: 3 });
draw.text('HF and particulates\nexhaust to filter plant').move(120, 62).font({ size: 13, fill: '#111' });

/* ---------- labels with leader lines ---------- */
function label(text, tx, ty, lx1, ly1, lx2, ly2, anchor) {
  draw.line(lx1, ly1, lx2, ly2).stroke({ color: '#111', width: 1.4 });
  draw.text(text).move(tx, ty).font({ size: 12, fill: '#111', anchor: anchor || 'start' });
}
label('Ceramic', 6, 250, 60, 256, 96, 256, 'start');
label('Steel shell', 6, 292, 66, 298, 84, 298, 'start');
label('Crust', 524, 210, 470, 218, 520, 216);
label('Bubbles of O₂, CO,\nand CO₂', 524, 288, 420, 296, 520, 296);
label('Al₂O₃ dissolved\nin molten Na₃AlF₆', 524, 336, 470, 350, 520, 344);
label('Molten aluminum', 524, 372, 470, 388, 520, 378);

/* ---------- interactive regions (hover/click) ---------- */
function hot(rect, tip, title, body) {
  rect.fill('#fff').opacity(0).css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(title, body); });
}
hot(draw.rect(472, 8).move(84, BATH_Y - 8), 'Frozen electrolyte crust', 'Crust',
  'A solid crust of frozen cryolite forms on top of the melt, insulating the cell and limiting heat loss. Alumina is fed through holes punched in this crust.');
hot(alLayer.clone().addTo(draw), 'Molten aluminum product', 'Molten aluminum',
  'Al³⁺ ions are reduced at the carbon cathode: Al³⁺ + 3e⁻ → Al(l). Being denser than the electrolyte, the liquid aluminum pools on the cell floor and is siphoned off periodically.');
hot(draw.rect(100, 122).move(150, 190), 'Carbon anode — consumed!', 'Carbon anodes (+)',
  'O²⁻ ions are oxidized at the anodes: 2 O²⁻ → O₂ + 4e⁻. The oxygen attacks the carbon, forming CO and CO₂, so the anodes are steadily consumed and must be replaced.');
hot(draw.rect(320, 22).move(120, 402), 'Cathode floor', 'Carbon cathode (−)',
  'The carbon-lined floor of the cell acts as the cathode, where aluminum ions gain electrons and deposit as molten metal.');

/* ---------- animation: ions, bubbles, electrons ---------- */
var dyn = draw.group();
var bubbles = [];
function spawnBubble() {
  var ax = Math.random() < 0.5 ? 200 : 360;
  var side = Math.random() < 0.5 ? -1 : 1;
  var x = ax + side * (52 + Math.random() * 10);
  var y = 250 + Math.random() * 55;
  var kinds = ['O₂', 'CO', 'CO₂'];
  var c = dyn.circle(4 + Math.random() * 4).move(x, y).fill('#fff').stroke({ color: '#ddd', width: 0.5 });
  bubbles.push({ el: c, x: x, y: y, vy: 0.5 + Math.random() * 0.7, kind: kinds[Math.floor(Math.random() * 3)] });
  c.css('cursor', 'pointer')
    .on('mousemove', (function (k) { return function (e) { showTooltip(k + ' bubble', e); }; })(bubbles[bubbles.length - 1].kind))
    .on('mouseleave', hideTooltip)
    .on('click', (function (k) { return function () { showPopup('Anode gas: ' + k, 'Oxygen liberated at the carbon anode reacts with the carbon itself, so the off-gas is a mixture of O₂, CO, and CO₂. This anode consumption is why the electrodes must be replaced regularly.'); }; })(bubbles[bubbles.length - 1].kind));
}
var ions = [];
function spawnIon() {
  // Al3+ drifts down to cathode; O2- drifts up to an anode
  if (Math.random() < 0.5) {
    var x = 100 + Math.random() * 420;
    var c = dyn.circle(5).move(x, BATH_Y + 14).fill('#4a90d9');
    ions.push({ el: c, x: x, y: BATH_Y + 14, vy: 0.6, type: 'al' });
  } else {
    var ax = Math.random() < 0.5 ? 200 : 360;
    var c = dyn.circle(5).move(ax + (Math.random() * 80 - 40), AL_BASE_Y - 30).fill('#d9534f');
    ions.push({ el: c, x: c.x(), y: AL_BASE_Y - 30, vy: 0.7, type: 'o', targetY: 320 });
  }
}

function frame() {
  if (!running) return;
  var rate = current / 50; // 1 at default
  if (Math.random() < 0.10 * rate) spawnBubble();
  if (Math.random() < 0.08 * rate) spawnIon();
  // bubbles rise
  for (var i = bubbles.length - 1; i >= 0; i--) {
    var b = bubbles[i];
    b.y -= b.vy * rate; b.x += Math.sin(b.y / 9) * 0.4;
    b.el.move(b.x, b.y);
    if (b.y < BATH_Y + 2) { b.el.remove(); bubbles.splice(i, 1); }
  }
  // ions migrate
  for (var j = ions.length - 1; j >= 0; j--) {
    var io = ions[j];
    if (io.type === 'al') {
      io.y += io.vy * rate;
      io.el.move(io.x, io.y);
      if (io.y >= alTopY - 4) {
        io.el.remove(); ions.splice(j, 1);
        alAmount += 1;
        document.getElementById('alScore').textContent = alAmount;
        // aluminum pool thickens (bounded)
        if (alTopY > 262) {
          alTopY -= 0.25;
          alLayer.move(84, alTopY).height(AL_BASE_Y - alTopY);
        }
      }
    } else {
      io.y -= io.vy * rate;
      io.el.move(io.x, io.y);
      if (io.y < io.targetY) {
        io.el.remove(); ions.splice(j, 1);
        spawnBubble(); // oxide becomes gas at the anode
      }
    }
  }
  // cap particles
  while (bubbles.length > 140) { bubbles[0].el.remove(); bubbles.shift(); }
  while (ions.length > 60) { ions[0].el.remove(); ions.shift(); }
  requestAnimationFrame(frame);
}

/* ---------- controls ---------- */
function toggle_anim() {
  running = !running;
  document.getElementById('animBtn').textContent = running ? '⏸ Pause' : '▶ Animate electrolysis';
  if (running) requestAnimationFrame(frame);
}
function update_current(v) { current = v; }
function trigger_reset() {
  running = false;
  document.getElementById('animBtn').textContent = '▶ Animate electrolysis';
  bubbles.forEach(function (b) { b.el.remove(); }); bubbles = [];
  ions.forEach(function (i) { i.el.remove(); }); ions = [];
  alAmount = 0; document.getElementById('alScore').textContent = 0;
  alTopY = 352; alLayer.move(84, alTopY).height(AL_BASE_Y - alTopY);
}

window.__markRendered();
// @FIGURE_CODE_END

